package dev.jarofcucumbers.prscraft;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
class SourceCompressionTest{
 @Test void unicodeBinaryEmptyAndSingleSymbolRoundTrip(){byte[] alphabet=new byte[256];for(int i=0;i<256;i++)alphabet[i]=(byte)i;for(byte[] bytes:new byte[][]{new byte[0],"Привіт 🌍! Їжак".getBytes(StandardCharsets.UTF_8),alphabet,new byte[1024]})for(String algorithm:List.of("rle","huffman")){var result=SourceCompression.encode(bytes,algorithm);assertArrayEquals(bytes,SourceCompression.decode(result.bytes()));assertEquals(result.bytes().length,result.headerBytes()+(result.payloadBits()+7)/8);}}
 @Test void runsSplitAt255AndMetadataCountsAgainstSavings(){byte[] input=new byte[1000];Arrays.fill(input,(byte)'A');var rle=SourceCompression.encode(input,"rle");assertEquals(19,rle.bytes().length);assertEquals(11,rle.headerBytes());assertTrue(SourceCompression.encode(input,"huffman").bytes().length<input.length);}
 @Test void uniformBytesHaveEightBitsEntropyAndHuffmanCanExpand(){byte[] bytes=new byte[1024];for(int i=0;i<bytes.length;i++)bytes[i]=(byte)i;var encoded=SourceCompression.encode(bytes,"huffman");assertEquals(8,encoded.entropy(),1e-12);assertEquals(8,encoded.averageCodeLength(),1e-12);assertTrue(encoded.bytes().length>bytes.length);assertArrayEquals(encoded.bytes(),SourceCompression.encode(bytes,"huffman").bytes());}
 @Test void malformedAndTruncatedContainersCannotProduceUnboundedOutput(){byte[] data=SourceCompression.encode("ABCDEABCDE".getBytes(StandardCharsets.UTF_8),"huffman").bytes();for(int n=0;n<data.length;n++){byte[] truncated=Arrays.copyOf(data,n);assertThrows(IllegalArgumentException.class,()->SourceCompression.decode(truncated));}byte[] wrong=data.clone();wrong[5]=(byte)255;wrong[6]=(byte)255;assertThrows(IllegalArgumentException.class,()->SourceCompression.decode(wrong));assertThrows(IllegalArgumentException.class,()->SourceCompression.decode(Arrays.copyOf(data,data.length+1)));}
 @Test void arbitraryInputsAndCorruptHeadersFailCleanly(){Random r=new Random(17);for(int i=0;i<100;i++){byte[] bytes=new byte[r.nextInt(500)];r.nextBytes(bytes);for(String algorithm:List.of("rle","huffman"))assertArrayEquals(bytes,SourceCompression.decode(SourceCompression.encode(bytes,algorithm).bytes()));try{SourceCompression.decode(bytes);}catch(IllegalArgumentException expected){}}}
 @Test void utf8IsStrictAndHexIsBounded(){assertThrows(IllegalArgumentException.class,()->MessageSettings.utf8(new byte[]{(byte)255}));assertThrows(IllegalArgumentException.class,()->MessageSettings.sourceBytes("utf8","\uD800"));assertArrayEquals(new byte[]{0,15,(byte)255},MessageSettings.sourceBytes("hex","00 0f FF"));assertThrows(IllegalArgumentException.class,()->MessageSettings.sourceBytes("hex","0"));assertThrows(IllegalArgumentException.class,()->MessageSettings.sourceBytes("utf8","А".repeat(513)));}
}
